// shared/signup.ts: imported by the browser and the server
import { s } from '@pyreon/validate'

export const Signup = s.object({
  email: s.string().email().serverCheck('email-unique', { message: 'Email already taken' }),
  password: s.string().min(10),
})

// client/signup.ts: cheap checks run, the server check is recorded as pending
import { Signup } from '../shared/signup'

const r = Signup.parse({ email: 'ada@example.com', password: 'correct horse' })
// r.ok === true, r.pending → [{ path: ['email'], key: 'email-unique' }]

// server/signup.ts: strict RFC 5322 email, disposable-domain blocklist, the DB check
import { registerServerCheck } from '@pyreon/validate/server'
import { Signup } from '../shared/signup'

registerServerCheck('email-unique', async (email) => !(await db.users.exists(email as string)))

async function handleSignup(body: unknown) {
  const verdict = await Signup.parseAsync(body)
  return verdict.ok ? { ok: true } : { ok: false, issues: verdict.issues }
}

