import { formatErrorsByPath, s } from '@pyreon/validate'

// every built-in issue carries an i18n key and params
const messages: Record<string, string> = {
  'validate.string.too-short': 'Mindestens {min} Zeichen',
  'validate.string.email': 'Ungültige E-Mail-Adresse',
}
const t = (key: string, params?: Record<string, unknown>) =>
  (messages[key] ?? key).replace(/\{(\w+)\}/g, (_, k: string) => String(params?.[k] ?? ''))

const Signup = s.object({ name: s.string().min(2), email: s.string().email() })

const r = Signup.parse({ name: 'A', email: 'nope' })
if (!r.ok) console.log(formatErrorsByPath(r.issues, t))
// { name: 'Mindestens 2 Zeichen', email: 'Ungültige E-Mail-Adresse' }

import { s } from '@pyreon/validate'
import { toJsonSchema } from '@pyreon/validate/json-schema'

const Ticket = s.object({
  title: s.string().min(3).describe('One-line summary'),
  priority: s.enum(['low', 'normal', 'urgent']),
  tags: s.array(s.string()).max(5).optional(),
})

// draft 2020-12, ready for an OpenAPI spec or an LLM's structured output
console.log(JSON.stringify(toJsonSchema(Ticket), null, 2))

// ...and the same schema checks what comes back
const reply = Ticket.parse(JSON.parse('{"title":"Login loops","priority":"urgent"}'))
console.log(reply.ok) // true

import { signal } from '@pyreon/reactivity'
import { parseReactive, s, watchValid } from '@pyreon/validate'

const Coupon = s.string().regex(/^[A-Z]{4}-\d{4}$/, { message: 'Looks like ABCD-1234' })
const code = signal('')

// a Computed result for templates...
const result = parseReactive(Coupon, code)
// ...and a callback that fires only when validity flips
const stop = watchValid(Coupon, code, (valid) => console.log('valid:', valid)) // valid: false

code.set('SAVE-2026') // valid: true
code.set('save') // valid: false
console.log(result().issues?.[0]?.message) // 'Looks like ABCD-1234'
stop()
